32	         "default": "import datetime\nimport json\nimport re\n\nWEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']\nMONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']\n\ndef parse_now(value):\n    \"\"\"'2031-03-07T11:00', '2031-03-07 11:00:00', '2031-03-07T11:00:00Z' or '2031-03-07' -> datetime.\"\"\"\n    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')\n    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):\n        try:\n            return datetime.datetime.strptime(s[:size], fmt)\n        except ValueError:\n            pass\n    raise ValueError('cannot read now: ' + s)\n\ndef parse_holidays(values):\n    \"\"\"ISO strings -> set of dates. Unreadable entries are skipped.\"\"\"\n    out = set()\n    for v in values or []:\n        try:\n            out.add(datetime.date.fromisoformat(str(v)[:10]))\n        except ValueError:\n            pass\n    return out\n\ndef is_business_day(d, holidays):\n    return d.weekday() < 5 and d not in holidays\n\ndef next_business_day(d, holidays, include_today=False):\n    \"\"\"The first business day after d (or d itself when include_today and d is one).\"\"\"\n    if include_today and is_business_day(d, holidays):\n        return d\n    d = d + datetime.timedelta(days=1)\n    while not is_business_day(d, holidays):\n        d = d + datetime.timedelta(days=1)\n    return d\n\ndef spoken_date(d):\n    \"\"\"'Friday 7 March'. Adapt the words to the brief's language.\"\"\"\n    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()\n\ntry:\n    now = parse_now(vars.get('now'))\n    hol = parse_holidays(['2031-03-14', '2031-04-02'])\n    today = now.date()\n    vars['today_spoken'] = spoken_date(today)\n    nxt = next_business_day(today, hol)\n    same_day = 'yes' if is_business_day(today, hol) and now.hour < 17 else 'no'\n    days = ('today (' + spoken_date(today) + ') after ' + now.strftime('%H:%M') + ' and ') if same_day == 'yes' else ''\n    vars['callback_window_text'] = 'A callback can be booked ' + days + 'on ' + spoken_date(nxt) + ', from 09:00 to 17:00. Today is ' + spoken_date(today) + ', ' + now.strftime('%H:%M') + '.'\n    vars['callback_next_day_iso'] = nxt.isoformat()\n    vars['calendar_state'] = 'ok'\nexcept Exception:\n    vars['today_spoken'] = ''\n    vars['callback_window_text'] = 'Ask for a time tomorrow between 09:00 and 17:00.'\n    vars['calendar_state'] = 'error'\nvars['close_outcome'] = 'outcome_w'\nvars['close_detail'] = 'detail_c'\nvars['promise_count'] = '0'\nvars['call_state'] = 'open'\n"
